SELECT 'gongkao', '等差数列', 'kp-xc-quantity-number-reasoning-arithmetic', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "等差数列"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心结论：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "等差数列是最基础的数列类型，相邻两项之差为常数d，公考中常考等差数列的变形和应用。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、知识要点"}]}, {"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "通项公式：an = a1 + (n-1)d，其中d为公差"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "等差中项：若a,b,c成等差数列，则b = (a+c)/2，即中间项等于两边的平均值"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "前n项和：Sn = n(a1+an)/2 = na1 + n(n-1)d/2"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "性质：若m+n = p+q，则am+an = ap+aq"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "变形：二级等差（相邻项的差成等差）、三级等差"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、解题方法"}]}, {"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "看相邻两项的差是否相等，判断是否为等差数列"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "差值不等时，再对差值做差（二级差），看是否为等差"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "利用等差中项验证：中间项是否等于两边的平均值"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "从选项反推：代入选项验证是否满足等差关系"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、易错点"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "只看一级差就下结论，忽略二级差的可能性"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "把等差数列和等比数列搞混"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "忽略负公差的情况（递减等差数列）"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "等差数列是数字推理的基础，必须首先掌握。建议先练一级差，再练二级差变形。"}]}]}]}$$ AS jsonb), NULL, '数量关系-数字推理-等差数列的核心知识点和解题方法。', category_node.id, CAST('["数量关系", "数字推理", "等差数列"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_quantity_number_reasoning_arithmetic", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
